/**
 * Zustand store for diagram state management
 */

import { create } from 'zustand';
import {
  DiagramNode,
  DiagramEdge,
  DiagramData,
  ViewportState
} from '../types/diagram';

interface DiagramState {
  // Nodes and edges
  nodes: DiagramNode[];
  edges: DiagramEdge[];

  // Viewport state
  viewport: ViewportState;

  // UI state
  selectedNodeId: string | null;
  isEditing: boolean;
  showMiniMap: boolean;

  // Actions
  setNodes: (nodes: DiagramNode[]) => void;
  setEdges: (edges: DiagramEdge[]) => void;
  addNode: (node: DiagramNode) => void;
  updateNode: (id: string, data: Partial<DiagramNode['data']>) => void;
  deleteNode: (id: string) => void;
  addEdge: (edge: DiagramEdge) => void;
  deleteEdge: (id: string) => void;
  setViewport: (viewport: ViewportState) => void;
  setSelectedNode: (id: string | null) => void;
  setIsEditing: (isEditing: boolean) => void;
  toggleMiniMap: () => void;
  resetDiagram: () => void;
  loadDiagram: (data: DiagramData) => void;
  getDiagram: () => DiagramData;
}

const initialViewport: ViewportState = {
  x: 0,
  y: 0,
  zoom: 1
};

export const useDiagramStore = create<DiagramState>((set, get) => ({
  // Initial state
  nodes: [
    {
      id: '1',
      type: 'custom',
      position: { x: 250, y: 0 },
      data: {
        label: 'Entry Point',
        type: 'entry',
        description: 'Application entry',
        color: '#06b6d4',
        editable: true
      }
    },
    {
      id: '2',
      type: 'custom',
      position: { x: 100, y: 150 },
      data: {
        label: 'Process Logic',
        type: 'logic',
        description: 'Main processing logic',
        color: '#8b5cf6',
        editable: true
      }
    },
    {
      id: '3',
      type: 'custom',
      position: { x: 400, y: 150 },
      data: {
        label: 'Data Storage',
        type: 'storage',
        description: 'Database operations',
        color: '#10b981',
        editable: true
      }
    },
    {
      id: '4',
      type: 'custom',
      position: { x: 250, y: 300 },
      data: {
        label: 'Exit Point',
        type: 'exit',
        description: 'Response handler',
        color: '#f59e0b',
        editable: true
      }
    }
  ],
  edges: [
    { id: 'e1-2', source: '1', target: '2', animated: true },
    { id: 'e1-3', source: '1', target: '3', animated: true },
    { id: 'e2-4', source: '2', target: '4' },
    { id: 'e3-4', source: '3', target: '4' }
  ],
  viewport: initialViewport,
  selectedNodeId: null,
  isEditing: false,
  showMiniMap: true,

  // Actions
  setNodes: (nodes) => set({ nodes }),

  setEdges: (edges) => set({ edges }),

  addNode: (node) => set((state) => ({
    nodes: [...state.nodes, node]
  })),

  updateNode: (id, data) => set((state) => ({
    nodes: state.nodes.map((node) =>
      node.id === id
        ? { ...node, data: { ...node.data, ...data } }
        : node
    )
  })),

  deleteNode: (id) => set((state) => ({
    nodes: state.nodes.filter((node) => node.id !== id),
    edges: state.edges.filter((edge) => edge.source !== id && edge.target !== id)
  })),

  addEdge: (edge) => set((state) => ({
    edges: [...state.edges, edge]
  })),

  deleteEdge: (id) => set((state) => ({
    edges: state.edges.filter((edge) => edge.id !== id)
  })),

  setViewport: (viewport) => set({ viewport }),

  setSelectedNode: (id) => set({ selectedNodeId: id }),

  setIsEditing: (isEditing) => set({ isEditing }),

  toggleMiniMap: () => set((state) => ({
    showMiniMap: !state.showMiniMap
  })),

  resetDiagram: () => set({
    nodes: get().nodes,
    edges: [],
    viewport: initialViewport,
    selectedNodeId: null,
    isEditing: false
  }),

  loadDiagram: (data) => set({
    nodes: data.nodes,
    edges: data.edges,
    viewport: initialViewport
  }),

  getDiagram: () => ({
    nodes: get().nodes,
    edges: get().edges
  })
}));

/**
 * WebSocket Client for real-time file watching
 * Connects to backend WebSocket server to receive file change events
 */

export type FileChangeEvent = {
  type: 'file:changed' | 'file:added' | 'file:deleted';
  path: string;
  timestamp: number;
  content?: string;
  previousContent?: string;
};

export type WebSocketMessage = FileChangeEvent | { type: 'connected' } | { type: 'error'; error: string };

type MessageHandler = (message: WebSocketMessage) => void;
type ConnectionChangeHandler = (isConnected: boolean) => void;

class WebSocketClient {
  private ws: WebSocket | null = null;
  private reconnectTimer: number | null = null;
  private messageHandlers: Set<MessageHandler> = new Set();
  private connectionHandlers: Set<ConnectionChangeHandler> = new Set();
  private reconnectAttempts = 0;
  private maxReconnectAttempts = 5;
  private reconnectDelay = 1000; // Start with 1 second
  private isWatching = false;

  constructor(private url: string = 'ws://localhost:3001') {}

  /**
   * Connect to WebSocket server
   */
  connect(): void {
    if (this.ws?.readyState === WebSocket.OPEN) {
      console.warn('WebSocket already connected');
      return;
    }

    try {
      this.ws = new WebSocket(this.url);

      this.ws.onopen = () => {
        console.log('WebSocket connected');
        this.reconnectAttempts = 0;
        this.reconnectDelay = 1000;
        this.notifyConnectionChange(true);

        // Send initial message
        this.sendMessage({ type: 'connected' });
      };

      this.ws.onmessage = (event) => {
        try {
          const message: WebSocketMessage = JSON.parse(event.data);
          this.notifyMessageHandlers(message);
        } catch (error) {
          console.error('Failed to parse WebSocket message:', error);
        }
      };

      this.ws.onclose = (event) => {
        console.log('WebSocket disconnected:', event.code, event.reason);
        this.notifyConnectionChange(false);

        // Attempt to reconnect if watching is enabled
        if (this.isWatching && this.reconnectAttempts < this.maxReconnectAttempts) {
          this.scheduleReconnect();
        }
      };

      this.ws.onerror = (error) => {
        console.error('WebSocket error:', error);
        this.notifyMessageHandlers({ type: 'error', error: 'Connection error' });
      };
    } catch (error) {
      console.error('Failed to create WebSocket connection:', error);
      this.notifyConnectionChange(false);
    }
  }

  /**
   * Disconnect from WebSocket server
   */
  disconnect(): void {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }

    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }

    this.isWatching = false;
    this.notifyConnectionChange(false);
  }

  /**
   * Start watching for file changes
   */
  startWatching(): void {
    this.isWatching = true;
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) {
      this.connect();
    }
  }

  /**
   * Stop watching for file changes
   */
  stopWatching(): void {
    this.isWatching = false;
    // Don't disconnect immediately, just stop reconnecting
  }

  /**
   * Check if currently connected
   */
  isConnected(): boolean {
    return this.ws?.readyState === WebSocket.OPEN;
  }

  /**
   * Check if currently watching
   */
  isActive(): boolean {
    return this.isWatching;
  }

  /**
   * Subscribe to WebSocket messages
   */
  onMessage(handler: MessageHandler): () => void {
    this.messageHandlers.add(handler);

    // Return unsubscribe function
    return () => {
      this.messageHandlers.delete(handler);
    };
  }

  /**
   * Subscribe to connection state changes
   */
  onConnectionChange(handler: ConnectionChangeHandler): () => void {
    this.connectionHandlers.add(handler);

    // Return unsubscribe function
    return () => {
      this.connectionHandlers.delete(handler);
    };
  }

  private sendMessage(message: any): void {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(message));
    }
  }

  private notifyMessageHandlers(message: WebSocketMessage): void {
    this.messageHandlers.forEach(handler => {
      try {
        handler(message);
      } catch (error) {
        console.error('Error in message handler:', error);
      }
    });
  }

  private notifyConnectionChange(isConnected: boolean): void {
    this.connectionHandlers.forEach(handler => {
      try {
        handler(isConnected);
      } catch (error) {
        console.error('Error in connection handler:', error);
      }
    });
  }

  private scheduleReconnect(): void {
    if (this.reconnectTimer) {
      return; // Already scheduled
    }

    console.log(`Reconnecting in ${this.reconnectDelay}ms (attempt ${this.reconnectAttempts + 1}/${this.maxReconnectAttempts})`);

    this.reconnectTimer = window.setTimeout(() => {
      this.reconnectTimer = null;
      this.reconnectAttempts++;
      this.reconnectDelay = Math.min(this.reconnectDelay * 2, 30000); // Exponential backoff, max 30s
      this.connect();
    }, this.reconnectDelay);
  }
}

// Singleton instance
let wsClient: WebSocketClient | null = null;

export function getWebSocketClient(): WebSocketClient {
  if (!wsClient) {
    wsClient = new WebSocketClient();
  }
  return wsClient;
}

export default WebSocketClient;

/**
 * Task types for CodeBaseCartographer
 * Defines task interface matching backend schema
 */

export type TaskStatus = 'pending' | 'in_progress' | 'completed' | 'blocked';
export type TaskPriority = 'low' | 'medium' | 'high' | 'critical';

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  priority: TaskPriority;
  files: string[];
  dependencies: string[];
  createdAt: number;
  updatedAt: number;
}

export interface CreateTaskInput {
  title: string;
  description?: string;
  status?: TaskStatus;
  priority?: TaskPriority;
  files?: string[];
  dependencies?: string[];
}

export interface UpdateTaskInput {
  title?: string;
  description?: string;
  status?: TaskStatus;
  priority?: TaskPriority;
  files?: string[];
  dependencies?: string[];
}

export interface TaskListResponse {
  tasks: Task[];
  count: number;
}

export interface TaskStats {
  [status: string]: number;
}

// Valid status transitions
export const STATUS_TRANSITIONS: Record<TaskStatus, TaskStatus[]> = {
  pending: ['in_progress', 'blocked'],
  in_progress: ['completed', 'blocked', 'pending'],
  completed: ['in_progress', 'pending'],
  blocked: ['pending', 'in_progress'],
};

