/**
 * File Version Store
 * Caches previous versions of files for diff comparison
 * Implements LRU eviction policy to manage memory
 */

interface FileVersion {
  content: string;
  timestamp: number;
  path: string;
}

interface StoredVersion extends FileVersion {
  lastAccessed: number;
}

class FileVersionStore {
  private store: Map<string, StoredVersion> = new Map();
  private maxVersions = 1000; // Maximum number of file versions to store
  private maxAge = 30 * 60 * 1000; // 30 minutes in milliseconds

  /**
   * Store a file version
   */
  storeVersion(path: string, content: string, timestamp?: number): void {
    const now = timestamp || Date.now();

    // Check if we already have a recent version
    const existing = this.store.get(path);
    if (existing && existing.content === content) {
      // Content hasn't changed, just update access time
      existing.lastAccessed = now;
      return;
    }

    // Add new version
    this.store.set(path, {
      path,
      content,
      timestamp: now,
      lastAccessed: now
    });

    // Evict old entries if necessary
    this.evictIfNeeded();
  }

  /**
   * Get previous version of a file
   */
  getPreviousVersion(path: string): FileVersion | null {
    const version = this.store.get(path);
    if (!version) {
      return null;
    }

    // Update last accessed time
    version.lastAccessed = Date.now();

    return {
      path: version.path,
      content: version.content,
      timestamp: version.timestamp
    };
  }

  /**
   * Check if a file has a previous version
   */
  hasPreviousVersion(path: string): boolean {
    return this.store.has(path);
  }

  /**
   * Remove a file version from the store
   */
  removeVersion(path: string): void {
    this.store.delete(path);
  }

  /**
   * Clear all stored versions
   */
  clear(): void {
    this.store.clear();
  }

  /**
   * Get statistics about the store
   */
  getStats(): { size: number; paths: string[] } {
    return {
      size: this.store.size,
      paths: Array.from(this.store.keys())
    };
  }

  /**
   * Evict old or excess entries
   */
  private evictIfNeeded(): void {
    const now = Date.now();

    // First, evict old entries
    for (const [path, version] of this.store.entries()) {
      if (now - version.lastAccessed > this.maxAge) {
        this.store.delete(path);
      }
    }

    // If still too many, evict least recently used
    if (this.store.size > this.maxVersions) {
      const entries = Array.from(this.store.entries())
        .sort((a, b) => a[1].lastAccessed - b[1].lastAccessed);

      const toRemove = entries.slice(0, this.store.size - this.maxVersions);
      toRemove.forEach(([path]) => this.store.delete(path));
    }
  }
}

// Singleton instance
let fileVersionStore: FileVersionStore | null = null;

export function getFileVersionStore(): FileVersionStore {
  if (!fileVersionStore) {
    fileVersionStore = new FileVersionStore();
  }
  return fileVersionStore;
}

export default FileVersionStore;

/**
 * Dagre-based auto-layout utility for diagram nodes
 */

import dagre from 'dagre';
import {
  DiagramNode,
  DiagramEdge,
  LayoutConfig
} from '../types/diagram';

const DEFAULT_LAYOUT_CONFIG: LayoutConfig = {
  direction: 'TB', // Top to Bottom
  nodeSpacing: 100,
  rankSpacing: 150
};

/**
 * Apply dagre auto-layout to nodes and edges
 */
export function applyAutoLayout(
  nodes: DiagramNode[],
  edges: DiagramEdge[],
  config: Partial<LayoutConfig> = {}
): { nodes: DiagramNode[]; edges: DiagramEdge[] } {
  const layoutConfig = { ...DEFAULT_LAYOUT_CONFIG, ...config };

  // Create a new directed graph
  const dagreGraph = new dagre.graphlib.Graph();
  dagreGraph.setDefaultEdgeLabel(() => ({}));

  // Set graph options
  dagreGraph.setGraph({
    rankdir: layoutConfig.direction,
    nodesep: layoutConfig.nodeSpacing,
    ranksep: layoutConfig.rankSpacing,
    edgesep: 50
  });

  // Add nodes to the graph
  nodes.forEach((node) => {
    dagreGraph.setNode(node.id, {
      width: node.width || 200,
      height: node.height || 80
    });
  });

  // Add edges to the graph
  edges.forEach((edge) => {
    dagreGraph.setEdge(edge.source, edge.target);
  });

  // Calculate layout
  dagre.layout(dagreGraph);

  // Apply calculated positions to nodes
  const layoutedNodes = nodes.map((node) => {
    const nodeWithPosition = dagreGraph.node(node.id);
    return {
      ...node,
      position: {
        x: nodeWithPosition.x - (node.width || 200) / 2,
        y: nodeWithPosition.y - (node.height || 80) / 2
      }
    };
  });

  return {
    nodes: layoutedNodes,
    edges
  };
}

/**
 * Calculate hierarchical levels for nodes
 */
export function calculateNodeLevels(
  nodes: DiagramNode[],
  edges: DiagramEdge[]
): Map<string, number> {
  const levels = new Map<string, number>();
  const visited = new Set<string>();

  // Find root nodes (no incoming edges)
  const inDegree = new Map<string, number>();
  nodes.forEach((node) => inDegree.set(node.id, 0));
  edges.forEach((edge) => {
    inDegree.set(
      edge.target,
      (inDegree.get(edge.target) || 0) + 1
    );
  });

  const roots = nodes.filter((node) => (inDegree.get(node.id) || 0) === 0);

  // BFS to calculate levels
  const queue: { id: string; level: number }[] = roots.map((r) => ({
    id: r.id,
    level: 0
  }));

  while (queue.length > 0) {
    const { id, level } = queue.shift()!;
    if (visited.has(id)) continue;
    visited.add(id);
    levels.set(id, level);

    // Find children and add to queue
    const children = edges.filter((e) => e.source === id);
    children.forEach((edge) => {
      if (!visited.has(edge.target)) {
        queue.push({ id: edge.target, level: level + 1 });
      }
    });
  }

  return levels;
}

/**
 * Detect cycles in the graph
 */
export function detectCycles(edges: DiagramEdge[]): string[][] {
  const cycles: string[][] = [];
  const visited = new Set<string>();
  const recursionStack = new Set<string>();
  const graph = new Map<string, string[]>();

  // Build adjacency list
  edges.forEach((edge) => {
    if (!graph.has(edge.source)) {
      graph.set(edge.source, []);
    }
    graph.get(edge.source)!.push(edge.target);
  });

  function dfs(node: string, path: string[]): void {
    visited.add(node);
    recursionStack.add(node);
    path.push(node);

    const neighbors = graph.get(node) || [];
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) {
        dfs(neighbor, [...path]);
      } else if (recursionStack.has(neighbor)) {
        // Found a cycle
        const cycleStart = path.indexOf(neighbor);
        if (cycleStart !== -1) {
          cycles.push([...path.slice(cycleStart), neighbor]);
        }
      }
    }

    recursionStack.delete(node);
  }

  // Check all nodes
  graph.forEach((_, node) => {
    if (!visited.has(node)) {
      dfs(node, []);
    }
  });

  return cycles;
}

/**
 * Validate diagram connectivity
 */
export function validateDiagramConnectivity(
  nodes: DiagramNode[],
  edges: DiagramEdge[]
): {
  isConnected: boolean;
  isolatedNodes: string[];
  disconnectedComponents: string[][];
} {
  const isolatedNodes: string[] = [];
  const components: string[][] = [];
  const visited = new Set<string>();

  // Find nodes with no connections
  const connectedNodes = new Set<string>();
  edges.forEach((edge) => {
    connectedNodes.add(edge.source);
    connectedNodes.add(edge.target);
  });

  nodes.forEach((node) => {
    if (!connectedNodes.has(node.id)) {
      isolatedNodes.push(node.id);
    }
  });

  // Find connected components using BFS
  const adjacencyList = new Map<string, string[]>();
  nodes.forEach((node) => adjacencyList.set(node.id, []));
  edges.forEach((edge) => {
    adjacencyList.get(edge.source)!.push(edge.target);
    adjacencyList.get(edge.target)!.push(edge.source);
  });

  function bfs(startNode: string): string[] {
    const component: string[] = [];
    const queue: string[] = [startNode];
    visited.add(startNode);

    while (queue.length > 0) {
      const node = queue.shift()!;
      component.push(node);

      const neighbors = adjacencyList.get(node) || [];
      for (const neighbor of neighbors) {
        if (!visited.has(neighbor)) {
          visited.add(neighbor);
          queue.push(neighbor);
        }
      }
    }

    return component;
  }

  nodes.forEach((node) => {
    if (!visited.has(node.id)) {
      components.push(bfs(node.id));
    }
  });

  return {
    isConnected: components.length <= 1,
    isolatedNodes,
    disconnectedComponents: components
  };
}

/**
 * useTasks hook - Task CRUD operations
 * Communicates with backend API at localhost:3000
 */

import { useState, useEffect, useCallback } from 'react';
import type {
  Task,
  CreateTaskInput,
  UpdateTaskInput,
  TaskListResponse,
  TaskStats,
} from '../types/task';

const API_BASE = 'http://localhost:3000/api';

export interface UseTasksResult {
  tasks: Task[];
  loading: boolean;
  error: string | null;
  stats: TaskStats | null;
  fetchTasks: () => Promise<void>;
  createTask: (input: CreateTaskInput) => Promise<Task>;
  updateTask: (id: string, input: UpdateTaskInput) => Promise<Task | null>;
  deleteTask: (id: string) => Promise<boolean>;
  fetchStats: () => Promise<void>;
  getTaskById: (id: string) => Task | undefined;
}

export function useTasks(): UseTasksResult {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [stats, setStats] = useState<TaskStats | null>(null);

  /**
   * Fetch all tasks from API
   */
  const fetchTasks = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`${API_BASE}/tasks`);
      if (!response.ok) {
        throw new Error(`Failed to fetch tasks: ${response.statusText}`);
      }

      const data: TaskListResponse = await response.json();
      setTasks(data.tasks);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Unknown error';
      setError(message);
      console.error('Error fetching tasks:', err);
    } finally {
      setLoading(false);
    }
  }, []);

  /**
   * Create a new task
   */
  const createTask = useCallback(async (input: CreateTaskInput): Promise<Task> => {
    setError(null);

    try {
      const response = await fetch(`${API_BASE}/tasks`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(input),
      });

      if (!response.ok) {
        throw new Error(`Failed to create task: ${response.statusText}`);
      }

      const task: Task = await response.json();
      setTasks((prev) => [task, ...prev]);
      return task;
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Unknown error';
      setError(message);
      console.error('Error creating task:', err);
      throw err;
    }
  }, []);

  /**
   * Update an existing task
   */
  const updateTask = useCallback(
    async (id: string, input: UpdateTaskInput): Promise<Task | null> => {
      setError(null);

      try {
        const response = await fetch(`${API_BASE}/tasks/${id}`, {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(input),
        });

        if (!response.ok) {
          throw new Error(`Failed to update task: ${response.statusText}`);
        }

        const task: Task = await response.json();
        setTasks((prev) =>
          prev.map((t) => (t.id === id ? task : t))
        );
        return task;
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Unknown error';
        setError(message);
        console.error('Error updating task:', err);
        return null;
      }
    },
    []
  );

  /**
   * Delete a task
   */
  const deleteTask = useCallback(async (id: string): Promise<boolean> => {
    setError(null);

    try {
      const response = await fetch(`${API_BASE}/tasks/${id}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error(`Failed to delete task: ${response.statusText}`);
      }

      setTasks((prev) => prev.filter((t) => t.id !== id));
      return true;
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Unknown error';
      setError(message);
      console.error('Error deleting task:', err);
      return false;
    }
  }, []);

  /**
   * Fetch task statistics
   */
  const fetchStats = useCallback(async () => {
    try {
      const response = await fetch(`${API_BASE}/tasks/stats/summary`);
      if (!response.ok) {
        throw new Error(`Failed to fetch stats: ${response.statusText}`);
      }

      const data: TaskStats = await response.json();
      setStats(data);
    } catch (err) {
      console.error('Error fetching stats:', err);
    }
  }, []);

  /**
   * Get a task by ID from local state
   */
  const getTaskById = useCallback(
    (id: string): Task | undefined => {
      return tasks.find((t) => t.id === id);
    },
    [tasks]
  );

  // Fetch tasks on mount
  useEffect(() => {
    fetchTasks();
    fetchStats();
  }, [fetchTasks, fetchStats]);

  return {
    tasks,
    loading,
    error,
    stats,
    fetchTasks,
    createTask,
    updateTask,
    deleteTask,
    fetchStats,
    getTaskById,
  };
}

/**
 * Diff Viewer Component
 * Displays side-by-side or unified diff with syntax highlighting
 */

import React, { useMemo } from 'react';
import * as Diff from 'diff';

interface DiffViewerProps {
  oldContent: string;
  newContent: string;
  filePath?: string;
  viewType?: 'side-by-side' | 'unified';
  language?: string;
}

interface DiffLine {
  lineNumber: number;
  content: string;
  type: 'added' | 'removed' | 'unchanged';
}

const DiffViewer: React.FC<DiffViewerProps> = ({
  oldContent,
  newContent,
  filePath,
  viewType = 'unified',
  language = 'text'
}) => {
  const diffLines = useMemo(() => {
    const changes = Diff.diffLines(oldContent, newContent);
    const lines: DiffLine[] = [];
    let oldLineNumber = 1;
    let newLineNumber = 1;

    changes.forEach((change) => {
      const type: DiffLine['type'] = change.added
        ? 'added'
        : change.removed
        ? 'removed'
        : 'unchanged';

      const content = change.value;
      const contentLines = content.split('\n').filter((line, i, arr) => {
        // Filter out the last empty line if present
        return !(i === arr.length - 1 && line === '');
      });

      contentLines.forEach((line) => {
        lines.push({
          lineNumber: type === 'removed' ? oldLineNumber++ : newLineNumber++,
          content: line,
          type
        });

        if (type === 'unchanged') {
          if (change.removed) oldLineNumber++;
          if (change.added) newLineNumber++;
        }
      });
    });

    return lines;
  }, [oldContent, newContent]);

  const highlightCode = (code: string, lang: string): string => {
    // Simple syntax highlighting - in production, you'd use a library like Prism.js or highlight.js
    // This is a basic implementation for demonstration

    if (lang === 'javascript' || lang === 'typescript' || lang === 'tsx' || lang === 'jsx') {
      return code
        .replace(/\/\/.*/g, '<span class="text-green-400">$&</span>') // Comments
        .replace(/('.*?'|".*?"|`.*?`)/g, '<span class="text-yellow-300">$&</span>') // Strings
        .replace(/\b(const|let|var|function|return|if|else|for|while|class|import|export|from|default)\b/g, '<span class="text-purple-400">$&</span>') // Keywords
        .replace(/\b(true|false|null|undefined)\b/g, '<span class="text-cyan-400">$&</span>') // Literals
        .replace(/\b(\d+)\b/g, '<span class="text-orange-400">$&</span>'); // Numbers
    }

    return code;
  };

  const renderLine = (line: DiffLine, index: number) => {
    const bgColor =
      line.type === 'added'
        ? 'bg-green-900/30'
        : line.type === 'removed'
        ? 'bg-red-900/30'
        : 'bg-transparent';

    const lineNumColor =
      line.type === 'added'
        ? 'text-green-500'
        : line.type === 'removed'
        ? 'text-red-500'
        : 'text-slate-600';

    const prefix = line.type === 'added' ? '+' : line.type === 'removed' ? '-' : ' ';

    return (
      <div
        key={index}
        className={`flex hover:bg-slate-800/50 ${bgColor} transition-colors`}
      >
        <span className={`w-16 text-right pr-4 select-none text-xs font-mono ${lineNumColor} border-r border-slate-800`}>
          {line.lineNumber}
        </span>
        <span className="w-6 text-center select-none text-xs font-mono text-slate-600">
          {prefix}
        </span>
        <code
          className="flex-1 px-2 text-sm font-mono whitespace-pre overflow-x-auto"
          dangerouslySetInnerHTML={{
            __html: highlightCode(line.content, language)
          }}
        />
      </div>
    );
  };

  const addedCount = diffLines.filter((l) => l.type === 'added').length;
  const removedCount = diffLines.filter((l) => l.type === 'removed').length;

  return (
    <div className="flex flex-col h-full bg-slate-950 border border-slate-700 rounded-lg overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-2 bg-slate-900 border-b border-slate-700">
        <div className="flex items-center gap-2">
          <span className="text-sm font-medium text-slate-200">Diff View</span>
          {filePath && (
            <span className="text-xs text-slate-400 font-mono truncate max-w-md">
              {filePath}
            </span>
          )}
        </div>
        <div className="flex items-center gap-4 text-xs">
          {removedCount > 0 && (
            <span className="text-red-400 font-medium">
              -{removedCount} lines
            </span>
          )}
          {addedCount > 0 && (
            <span className="text-green-400 font-medium">
              +{addedCount} lines
            </span>
          )}
        </div>
      </div>

      {/* Diff Content */}
      <div className="flex-1 overflow-y-auto">
        {diffLines.length === 0 ? (
          <div className="flex items-center justify-center h-full text-slate-500">
            No changes detected
          </div>
        ) : (
          <div className="font-mono text-xs">
            {diffLines.map((line, index) => renderLine(line, index))}
          </div>
        )}
      </div>
    </div>
  );
};

export default DiffViewer;

/**
 * Custom node component for React Flow with inline editing
 */

import React, { useState, useRef, useEffect } from 'react';
import { Handle, Position, NodeProps } from '@xyflow/react';
import { DiagramNodeData } from '../types/diagram';

const NODE_TYPE_COLORS = {
  entry: '#06b6d4', // cyan
  logic: '#8b5cf6', // purple
  storage: '#10b981', // green
  exit: '#f59e0b', // amber
  external: '#6b7280', // gray
  decision: '#ef4444', // red
  process: '#3b82f6' // blue
};

const NODE_TYPE_ICONS = {
  entry: '⚡',
  logic: '⚙️',
  storage: '💾',
  exit: '🚪',
  external: '🔌',
  decision: '🔀',
  process: '⚗️'
};

export default function DiagramNode({
  data,
  selected,
  id
}: NodeProps<DiagramNodeData>) {
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState(data.label);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isEditing && inputRef.current) {
      inputRef.current.focus();
      inputRef.current.select();
    }
  }, [isEditing]);

  const handleDoubleClick = () => {
    if (data.editable !== false) {
      setIsEditing(true);
    }
  };

  const handleBlur = () => {
    setIsEditing(false);
    if (editValue !== data.label && editValue.trim()) {
      // Trigger update through store or callback
      data.onLabelChange?.(id, editValue.trim());
    } else {
      setEditValue(data.label);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleBlur();
    } else if (e.key === 'Escape') {
      setEditValue(data.label);
      setIsEditing(false);
    }
  };

  const nodeColor = data.color || NODE_TYPE_COLORS[data.type] || '#6b7280';
  const nodeIcon = NODE_TYPE_ICONS[data.type] || '📦';

  return (
    <div
      className={`relative px-4 py-3 rounded-lg border-2 bg-slate-900 shadow-xl transition-all ${
        selected ? 'ring-2 ring-cyan-400 ring-offset-2 ring-offset-slate-900' : ''
      }`}
      style={{
        borderColor: nodeColor,
        minWidth: '150px',
        maxWidth: '250px'
      }}
      onDoubleClick={handleDoubleClick}
    >
      {/* Input handle (top) */}
      <Handle
        type="target"
        position={Position.Top}
        className="w-3 h-3 !bg-slate-500 !border-2 !border-slate-400"
      />

      {/* Node header */}
      <div className="flex items-center gap-2 mb-2">
        <span className="text-lg" style={{ color: nodeColor }}>
          {nodeIcon}
        </span>
        {isEditing ? (
          <input
            ref={inputRef}
            type="text"
            value={editValue}
            onChange={(e) => setEditValue(e.target.value)}
            onBlur={handleBlur}
            onKeyDown={handleKeyDown}
            className="flex-1 bg-slate-800 text-white text-sm font-semibold px-2 py-1 rounded border border-slate-600 focus:outline-none focus:border-cyan-500"
          />
        ) : (
          <span className="text-sm font-semibold text-slate-100 flex-1">
            {data.label}
          </span>
        )}
      </div>

      {/* Node description */}
      {data.description && !isEditing && (
        <div className="text-xs text-slate-400 mt-1">
          {data.description}
        </div>
      )}

      {/* Type badge */}
      <div className="mt-2">
        <span
          className="text-[10px] px-2 py-0.5 rounded-full uppercase tracking-wider font-medium"
          style={{
            backgroundColor: `${nodeColor}20`,
            color: nodeColor
          }}
        >
          {data.type}
        </span>
      </div>

      {/* Edit hint */}
      {data.editable !== false && (
        <div className="absolute -bottom-5 left-1/2 -translate-x-1/2 opacity-0 hover:opacity-100 transition-opacity text-[10px] text-slate-500 whitespace-nowrap">
          Double-click to edit
        </div>
      )}

      {/* Output handle (bottom) */}
      <Handle
        type="source"
        position={Position.Bottom}
        className="w-3 h-3 !bg-slate-500 !border-2 !border-slate-400"
      />

      {/* Left handle */}
      <Handle
        type="target"
        position={Position.Left}
        id="left"
        className="w-3 h-3 !bg-slate-500 !border-2 !border-slate-400"
      />

      {/* Right handle */}
      <Handle
        type="source"
        position={Position.Right}
        id="right"
        className="w-3 h-3 !bg-slate-500 !border-2 !border-slate-400"
      />
    </div>
  );
}

/**
 * File Change Notification Component
 * Displays toast notifications for file changes with "View Diff" button
 */

import React, { useState, useEffect } from 'react';

export interface FileChange {
  id: string;
  type: 'file:changed' | 'file:added' | 'file:deleted';
  path: string;
  timestamp: number;
}

interface FileChangeNotificationProps {
  changes: FileChange[];
  onViewDiff?: (path: string) => void;
  autoDismiss?: boolean;
  dismissDelay?: number;
}

const FileChangeNotification: React.FC<FileChangeNotificationProps> = ({
  changes,
  onViewDiff,
  autoDismiss = true,
  dismissDelay = 5000
}) => {
  const [dismissed, setDismissed] = useState<Set<string>>(new Set());

  useEffect(() => {
    if (autoDismiss) {
      changes.forEach((change) => {
        const timer = setTimeout(() => {
          setDismissed((prev) => new Set(prev).add(change.id));
        }, dismissDelay);

        return () => clearTimeout(timer);
      });
    }
  }, [changes, autoDismiss, dismissDelay]);

  const handleDismiss = (id: string) => {
    setDismissed((prev) => new Set(prev).add(id));
  };

  const visibleChanges = changes.filter((c) => !dismissed.has(c.id));

  if (visibleChanges.length === 0) {
    return null;
  }

  const getChangeIcon = (type: FileChange['type']) => {
    switch (type) {
      case 'file:added':
        return '📄';
      case 'file:deleted':
        return '🗑️';
      case 'file:changed':
        return '✏️';
      default:
        return '📝';
    }
  };

  const getChangeColor = (type: FileChange['type']) => {
    switch (type) {
      case 'file:added':
        return 'border-green-500/50 bg-green-900/20';
      case 'file:deleted':
        return 'border-red-500/50 bg-red-900/20';
      case 'file:changed':
        return 'border-yellow-500/50 bg-yellow-900/20';
      default:
        return 'border-slate-600 bg-slate-800';
    }
  };

  const getChangeLabel = (type: FileChange['type']) => {
    switch (type) {
      case 'file:added':
        return 'File added';
      case 'file:deleted':
        return 'File deleted';
      case 'file:changed':
        return 'File changed';
      default:
        return 'File modified';
    }
  };

  return (
    <div className="fixed bottom-4 right-4 z-50 flex flex-col gap-2 max-w-md w-full">
      {visibleChanges.map((change) => (
        <div
          key={change.id}
          className={`p-4 rounded-lg border shadow-lg backdrop-blur-sm ${getChangeColor(
            change.type
          )} animate-slide-in transition-all`}
        >
          <div className="flex items-start gap-3">
            <span className="text-xl">{getChangeIcon(change.type)}</span>
            <div className="flex-1 min-w-0">
              <div className="flex items-center justify-between gap-2 mb-1">
                <span className="text-sm font-medium text-slate-200">
                  {getChangeLabel(change.type)}
                </span>
                <button
                  onClick={() => handleDismiss(change.id)}
                  className="text-slate-400 hover:text-white transition-colors"
                  aria-label="Dismiss"
                >
                  ✕
                </button>
              </div>
              <p className="text-xs text-slate-400 font-mono truncate mb-2">
                {change.path}
              </p>
              {change.type !== 'file:deleted' && onViewDiff && (
                <button
                  onClick={() => onViewDiff(change.path)}
                  className="w-full py-2 px-3 bg-cyan-600 hover:bg-cyan-500 text-white text-sm font-medium rounded-lg transition-colors"
                >
                  View Diff
                </button>
              )}
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

export default FileChangeNotification;

