/**
 * React Flow-based diagram canvas component
 */

import React, { useCallback, useMemo } from 'react';
import {
  ReactFlow,
  Background,
  Controls,
  MiniMap,
  NodeTypes,
  EdgeTypes,
  Connection,
  Edge,
  addEdge,
  useNodesState,
  useEdgesState,
  BackgroundVariant
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import { useDiagramStore } from '../stores/useDiagramStore';
import { applyAutoLayout } from '../utils/diagramLayout';
import DiagramNode from './DiagramNode';
import { DiagramNodeData } from '../types/diagram';

// Register custom node type
const nodeTypes: NodeTypes = {
  custom: DiagramNode
};

// Custom edge styles
const defaultEdgeOptions = {
  animated: true,
  style: { stroke: '#64748b', strokeWidth: 2 }
};

export default function DiagramView() {
  const {
    nodes: storeNodes,
    edges: storeEdges,
    showMiniMap,
    addNode,
    updateNode,
    addEdge: addStoreEdge,
    deleteEdge
  } = useDiagramStore();

  const [nodes, setNodes, onNodesChange] = useNodesState(storeNodes);
  const [edges, setEdges, onEdgesChange] = useEdgesState(storeEdges);

  // Sync store state with local state
  React.useEffect(() => {
    setNodes(storeNodes);
  }, [storeNodes, setNodes]);

  React.useEffect(() => {
    setEdges(storeEdges);
  }, [storeEdges, setEdges]);

  // Handle new connections
  const onConnect = useCallback(
    (connection: Connection) => {
      const newEdge = {
        ...connection,
        id: `e${connection.source}-${connection.target}`,
        animated: true,
        style: { stroke: '#64748b', strokeWidth: 2 }
      };
      setEdges((eds) => addEdge(connection, eds));
      addStoreEdge(newEdge);
    },
    [setEdges, addStoreEdge]
  );

  // Handle node updates
  const onNodeDoubleClick = useCallback(
    (_: any, node: any) => {
      // Trigger inline editing
      updateNode(node.id, { editable: true });
    },
    [updateNode]
  );

  // Apply auto-layout
  const handleAutoLayout = useCallback(() => {
    const layouted = applyAutoLayout(nodes, edges, {
      direction: 'TB',
      nodeSpacing: 100,
      rankSpacing: 150
    });
    setNodes(layouted.nodes);
  }, [nodes, edges, setNodes]);

  // Add new node
  const handleAddNode = useCallback(() => {
    const newNodeId = `node-${Date.now()}`;
    const newNode = {
      id: newNodeId,
      type: 'custom',
      position: { x: Math.random() * 400 + 100, y: Math.random() * 300 + 100 },
      data: {
        label: 'New Node',
        type: 'process',
        description: 'Add description',
        color: '#3b82f6',
        editable: true
      }
    };
    addNode(newNode);
  }, [addNode]);

  // Handle edge deletion
  const onEdgesDelete = useCallback(
    (_: any) => {
      // Handle edge deletion in store
    },
    []
  );

  // MiniMap node colors
  const minimapNodeColor = useCallback((node: any) => {
    return node.data.color || '#6b7280';
  }, []);

  return (
    <div className="w-full h-full bg-slate-950 relative">
      {/* Toolbar */}
      <div className="absolute top-4 left-4 z-10 flex gap-2">
        <button
          onClick={handleAutoLayout}
          className="px-4 py-2 bg-cyan-600 hover:bg-cyan-500 text-white text-sm font-medium rounded-lg shadow-lg transition-colors flex items-center gap-2"
        >
          <span>📐</span> Auto Layout
        </button>
        <button
          onClick={handleAddNode}
          className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-sm font-medium rounded-lg shadow-lg transition-colors flex items-center gap-2"
        >
          <span>➕</span> Add Node
        </button>
      </div>

      {/* React Flow Canvas */}
      <ReactFlow
        nodes={nodes.map((node) => ({
          ...node,
          data: {
            ...node.data,
            onLabelChange: (id: string, newLabel: string) => {
              updateNode(id, { label: newLabel });
            }
          }
        }))}
        edges={edges}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onConnect={onConnect}
        onNodeDoubleClick={onNodeDoubleClick}
        onEdgesDelete={onEdgesDelete}
        nodeTypes={nodeTypes}
        defaultEdgeOptions={defaultEdgeOptions}
        fitView
        className="bg-slate-950"
      >
        <Background
          variant={BackgroundVariant.Dots}
          gap={16}
          size={1}
          color="#334155"
        />
        <Controls
          className="!bg-slate-900 !border !border-slate-700"
          showZoom={true}
          showFitView={true}
          showInteractive={true}
        />
        {showMiniMap && (
          <MiniMap
            nodeColor={minimapNodeColor}
            nodeStrokeWidth={3}
            nodeBorderRadius={8}
            pannable
            zoomable
            className="!bg-slate-900 !border !border-slate-700"
          />
        )}
      </ReactFlow>

      {/* Instructions */}
      <div className="absolute bottom-4 left-4 z-10 bg-slate-900/90 backdrop-blur border border-slate-700 rounded-lg p-3 text-xs text-slate-400">
        <div className="font-semibold text-slate-300 mb-1">Controls:</div>
        <ul className="space-y-1">
          <li>• Drag nodes to reposition</li>
          <li>• Double-click to edit labels</li>
          <li>• Connect from dots on edges</li>
          <li>• Scroll to zoom, drag to pan</li>
        </ul>
      </div>
    </div>
  );
}

/**
 * Watch Mode Toggle Component
 * Enables/disables real-time file watching
 */

import React, { useState, useEffect } from 'react';
import { getWebSocketClient } from '../services/websocketClient';

interface WatchModeToggleProps {
  onEnabledChange?: (enabled: boolean) => void;
  className?: string;
}

const WatchModeToggle: React.FC<WatchModeToggleProps> = ({
  onEnabledChange,
  className = ''
}) => {
  const [isWatching, setIsWatching] = useState(false);
  const [isConnected, setIsConnected] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);

  useEffect(() => {
    const wsClient = getWebSocketClient();

    // Check initial state
    setIsConnected(wsClient.isConnected());
    setIsWatching(wsClient.isActive());

    // Subscribe to connection changes
    const unsubscribe = wsClient.onConnectionChange((connected) => {
      setIsConnected(connected);
      setIsConnecting(false);
    });

    return () => {
      unsubscribe();
    };
  }, []);

  const handleToggle = () => {
    const wsClient = getWebSocketClient();

    if (isWatching) {
      // Stop watching
      wsClient.stopWatching();
      setIsWatching(false);
      onEnabledChange?.(false);
    } else {
      // Start watching
      setIsConnecting(true);
      wsClient.startWatching();
      setIsWatching(true);
      onEnabledChange?.(true);
    }
  };

  const getStatusColor = () => {
    if (isConnecting) {
      return 'bg-yellow-500';
    }
    if (isConnected && isWatching) {
      return 'bg-green-500';
    }
    return 'bg-slate-500';
  };

  const getStatusText = () => {
    if (isConnecting) {
      return 'Connecting...';
    }
    if (isConnected && isWatching) {
      return 'Watching';
    }
    if (isWatching) {
      return 'Reconnecting...';
    }
    return 'Paused';
  };

  return (
    <div className={`flex items-center justify-between ${className}`}>
      <div className="flex items-center gap-2">
        <span className="text-sm text-slate-400">Watch Mode</span>
        <div className="flex items-center gap-1.5">
          <span
            className={`w-2 h-2 rounded-full ${getStatusColor()} ${
              isConnected && isWatching ? 'animate-pulse' : ''
            }`}
          />
          <span className="text-xs text-slate-500">{getStatusText()}</span>
        </div>
      </div>
      <button
        onClick={handleToggle}
        disabled={isConnecting}
        className={`
          relative w-10 h-6 rounded-full p-1 transition-colors duration-200
          ${isWatching ? 'bg-cyan-600' : 'bg-slate-700'}
          ${isConnecting ? 'opacity-50 cursor-not-allowed' : 'hover:opacity-90'}
        `}
        aria-label={isWatching ? 'Disable watch mode' : 'Enable watch mode'}
      >
        <span
          className={`
            block w-4 h-4 bg-white rounded-full transition-transform duration-200
            ${isWatching ? 'translate-x-4' : 'translate-x-0'}
          `}
        />
      </button>
    </div>
  );
};

export default WatchModeToggle;

/**
 * View toggle component for switching between Node View and Flow Chart
 */

import React from 'react';
import { AppMode } from '../types';

interface ViewToggleProps {
  currentMode: AppMode;
  onModeChange: (mode: AppMode) => void;
}

export default function ViewToggle({ currentMode, onModeChange }: ViewToggleProps) {
  return (
    <div className="flex items-center gap-2 bg-slate-900/50 backdrop-blur border border-slate-700 rounded-lg p-1">
      <button
        onClick={() => onModeChange(AppMode.CHAT)}
