      const edgeId = store.edges[0].id;
      const initialLength = store.edges.length;

      store.deleteEdge(edgeId);

      const state = useDiagramStore.getState();
      expect(state.edges).toHaveLength(initialLength - 1);
      expect(state.edges.find((e) => e.id === edgeId)).toBeUndefined();
    });
