  entry: '⚡',
  logic: '⚙️',
  storage: '💾',
  exit: '🚪',
  external: '🔌',
  decision: '🔀',
  process: '⚗️'
};

export default function DiagramNode({
  data,
  selected,
  id
}: NodeProps<DiagramNodeData>) {
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState(data.label);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isEditing && inputRef.current) {
      inputRef.current.focus();
      inputRef.current.select();
    }
  }, [isEditing]);

  const handleDoubleClick = () => {
    if (data.editable !== false) {
      setIsEditing(true);
    }
  };

  const handleBlur = () => {
    setIsEditing(false);
    if (editValue !== data.label && editValue.trim()) {
      // Trigger update through store or callback
      data.onLabelChange?.(id, editValue.trim());
    } else {
      setEditValue(data.label);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleBlur();
    } else if (e.key === 'Escape') {
      setEditValue(data.label);
      setIsEditing(false);
    }
  };

  const nodeColor = data.color || NODE_TYPE_COLORS[data.type] || '#6b7280';
  const nodeIcon = NODE_TYPE_ICONS[data.type] || '📦';

